SELECT a.account_type, ROUND((100 * SUM(CASE WHEN t.txn_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit, COUNT(CASE WHEN t.merchant = 'Amazon' THEN 1 END) AS amazon_count FROM transactions t INNER JOIN accounts a ON a.id = t.account_id WHERE a.customer_id IS NOT NULL GROUP BY a.account_type HAVING ROUND((100 * SUM(CASE WHEN t.txn_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 79;
